export const THEME_SELECTOR_DEFAULTS: ThemeSelectorStrings = {
  label: "Select theme",
  rebrand: "Rebrand",
  canvas: "Canvas",
  canvasHighContrast: "Canvas high contrast",
  colorLabel: "Color scheme",
  navy: "Navy",
  blue: "Blue",
  green: "Green",
  red: "Red",
  orange: "Orange",
  grey: "Grey",
  ash: "Ash",
  plum: "Plum",
  violet: "Violet",
