{"code":"return page.evaluate(() => {
  document.documentElement.setAttribute('dir', 'rtl');
  const imgLight = document.querySelector('.VPNavBarTitle img.logo.light');
  const title = document.querySelector('.VPNavBarTitle .title');
  const imgRect = imgLight.getBoundingClientRect();

  // Create a debug marker exactly over the dot in the image
  // The dot in SVG is at cx=787.3 in viewBox 108.948 to 805.2 (width 696.252)
  // Relative x ratio = (787.3 - 108.948) / 696.252 = 678.352 / 696.252 = ~0.97429
  // Relative y ratio = (225.5 - 121.056) / 123.284 = 104.444 / 123.284 = ~0.84718
  const dotXInImg = (787.3 - 108.948) / 696.252 * imgRect.width;
  const dotYInImg = (225.5 - 121.056) / 123.284 * imgRect.height;

  const actualDotPageX = imgRect.left + dotXInImg;
  const actualDotPageY = imgRect.top + dotYInImg;

  // Now let's check ::after style in RTL
  const afterStyle = window.getComputedStyle(title, '::after');

  return {
    imgRect,
    dotXInImg,
    dotYInImg,
    actualDotPageX,
    actualDotPageY,
    afterLeft: afterStyle.left,
    afterRight: afterStyle.right,
    afterDirection: afterStyle.direction,
  };
});","pageId":"a710fdd8-5b64-4fa5-a877-def73fa7ca88"}

