{"content":"/**
 * `@pantoken/plugin-custom-theme-colors` — custom theme color rules and hero/brand variables.
 *
 * Emits scoped `:root[data-pantoken-color="…"]` and `:root[data-pantoken-theme="canvasHighContrast"][data-pantoken-color="…"]`
 * rules for all 14 color namespaces (`navy`, `blue`, `green`, `red`, `orange`, `grey`, `ash`, `plum`, `violet`, `stone`, `sky`, `honey`, `sea`, `aurora`).
 *
 * @example
 * ```ts
 * import { toCss } from "@pantoken/css";
 * import { byTheme } from "@pantoken/tokens";
 * import { customThemeColors } from "@pantoken/plugin-custom-theme-colors";
 *
 * const css = toCss(byTheme("rebrand"), { plugins: [customThemeColors()] });
 * ```
 *
 * @module
 * @beta
 */
import { definePlugin } from "@pantoken/plugin-kit";
import { byTheme } from "@pantoken/tokens";
import type { PantokenPlugin, Token } from "@pantoken/model";

/** The 14 available color namespaces for site theme color selection. */
export const COLOR_KEYS = [
  "navy",
  "blue",
  "green",
  "red",
  "orange",
  "grey",
  "ash",
  "plum",
  "violet",
  "stone",
  "sky",
  "honey",
  "sea",
  "aurora",
] as const;

/** A supported custom theme color namespace. */
export type PantokenColorNamespace = (typeof COLOR_KEYS)[number];

/** Options for the {@link customThemeColors} plugin. */
export interface CustomThemeColorsOptions {
  /** Optional token array or map to resolve primitive step color values from. */
  tokens?: readonly Token[] | Map<string, string>;
}

/**
 * Generate CSS rules for all custom theme color choices (brand tokens, hero background image/colors, hero text, and primary CTA button).
 *
 * @param tokens - Optional token array or map for primitive step color lookups.
 * @returns Generated CSS rules string.
 */
export function customThemeColorsCss(tokens?: readonly Token[] | Map<string, string>): string {
  const tokenMap = new Map<string, string>();

  if (tokens instanceof Map) {
    for (const [k, v] of tokens.entries()) tokenMap.set(k, v);
  } else if (Array.isArray(tokens)) {
    for (const t of tokens) tokenMap.set(t.name, t.value);
  } else {
    for (const t of byTheme("rebrand")) tokenMap.set(t.name, t.value);
  }

  return COLOR_KEYS.map((c) => {
    const scale = c === "ash" ? "grey" : c;

    function getHex(step: number): string {
      const tokenName = `--instui-primitive-color-${scale}-${scale}${step}`;
      return tokenMap.get(tokenName) ?? "#1D354F";
    }

    function makeHeroSvgUrl(): string {
      const c1 = encodeURIComponent(getHex(200));
      const c2 = encodeURIComponent(getHex(160));
      const c3 = encodeURIComponent(getHex(120));
      const c4 = encodeURIComponent(getHex(80));
      const svg = `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 374 160'><rect width='374' height='160' fill='${c1}'/><circle cx='374' cy='160' r='200' fill='${c2}'/><circle cx='374' cy='160' r='140' fill='${c3}'/><circle cx='374' cy='160' r='80' fill='${c4}'/></svg>`;
      return `url("data:image/svg+xml,${svg}")`;
    }

    const rebrandRule = `:root[data-pantoken-color="${c}"] {
  --instui-color-institutional-brand-primary: light-dark(var(--instui-primitive-color-${scale}-${scale}170), var(--instui-primitive-color-${scale}-${scale}10));
  --instui-color-institutional-brand-button-primary-bgd: light-dark(var(--instui-primitive-color-${scale}-${scale}170), var(--instui-primitive-color-${scale}-${scale}10));
  --instui-color-institutional-brand-button-primary-text: light-dark(var(--instui-primitive-color-white), var(--instui-primitive-color-${scale}-${scale}170));
  --instui-color-institutional-brand-button-secondary-bgd: light-dark(var(--instui-primitive-color-${scale}-${scale}110), var(--instui-primitive-color-${scale}-${scale}60));
  --instui-color-institutional-brand-button-secondary-text: light-dark(var(--instui-primitive-color-${scale}-${scale}170), var(--instui-primitive-color-white));
  --vp-home-bg-image: ${makeHeroSvgUrl()};
  --vp-home-bg-color: ${getHex(200)};
  --vp-home-hero-name-color: var(--instui-primitive-color-${scale}-${scale}50);
  --vp-home-hero-name-background: linear-gradient(135deg, var(--instui-primitive-color-${scale}-${scale}30), var(--instui-primitive-color-${scale}-${scale}60));
  --vp-button-brand-bg: var(--instui-primitive-color-${scale}-${scale}40);
  --vp-button-brand-hover-bg: var(--instui-primitive-color-${scale}-${scale}30);
  --vp-button-brand-active-bg: var(--instui-primitive-color-${scale}-${scale}30);
  --vp-button-brand-text: var(--instui-primitive-color-${scale}-${scale}190);
  --vp-button-brand-hover-text: var(--instui-primitive-color-${scale}-${scale}190);
  --vp-button-brand-active-text: var(--instui-primitive-color-${scale}-${scale}190);
  --vp-button-brand-border: var(--instui-primitive-color-${scale}-${scale}40);
  --vp-button-brand-hover-border: var(--instui-primitive-color-${scale}-${scale}30);
  --vp-button-brand-active-border: var(--instui-primitive-color-${scale}-${scale}30);
}`;

    const hcRule = `:root[data-pantoken-theme="canvasHighContrast"][data-pantoken-color="${c}"] {
  --instui-color-institutional-brand-primary: var(--instui-primitive-color-${scale}-${scale}180);
  --instui-color-institutional-brand-button-primary-bgd: var(--instui-primitive-color-${scale}-${scale}180);
  --instui-color-institutional-brand-button-primary-text: var(--instui-primitive-color-white);
  --instui-color-institutional-brand-button-secondary-bgd: var(--instui-primitive-color-${scale}-${scale}140);
  --instui-color-institutional-brand-button-secondary-text: var(--instui-primitive-color-${scale}-${scale}190);
}`;

    return `${rebrandRule}\n\n${hcRule}`;
  }).join("\n\n");
}

/**
 * Create the custom theme colors plugin.
 *
 * @param options - {@link CustomThemeColorsOptions}.
 * @returns A {@link PantokenPlugin} with a `css` hook.
 */
export function customThemeColors(options: CustomThemeColorsOptions = {}): PantokenPlugin {
  return definePlugin({
    name: "@pantoken/plugin-custom-theme-colors",
    css: (ctx) => ({
      marker: "pantoken:custom-theme-colors",
      append: customThemeColorsCss(options.tokens ?? ctx?.tokens),
    }),
  });
}

export default customThemeColors;
