{"code":"return page.evaluate(() => {
  let styleEl = document.getElementById('test-logo-dot');
  if (!styleEl) {
    styleEl = document.createElement('style');
    styleEl.id = 'test-logo-dot';
    document.head.appendChild(styleEl);
  }

  styleEl.textContent = `
    .VPNavBarTitle .title {
      position: relative;
      display: inline-flex;
      align-items: center;
    }
    .VPNavBarTitle .title::after {
      content: "";
      position: absolute;
      top: calc(50% - 12px);
      left: 0;
      width: calc(24px * 696.252 / 123.284);
      height: 24px;
      background-color: #ff0000;
      -webkit-mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%27108.948%20121.056%20696.252%20123.284%27%3E%3Ccircle%20cx%3D%27787.3%27%20cy%3D%27225.5%27%20r%3D%2713.9%27%20fill%3D%27black%27%2F%3E%3C%2Fsvg%3E") no-repeat center / contain;
      mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%27108.948%20121.056%20696.252%20123.284%27%3E%3Ccircle%20cx%3D%27787.3%27%20cy%3D%27225.5%27%20r%3D%2713.9%27%20fill%3D%27black%27%2F%3E%3C%2Fsvg%3E") no-repeat center / contain;
      pointer-events: none;
    }
    html[dir="rtl"] .VPNavBarTitle .title::after {
      left: auto;
      right: 0;
    }
  `;

  const imgLight = document.querySelector('.VPNavBarTitle img.logo.light');
  const title = document.querySelector('.VPNavBarTitle .title');
  const imgRect = imgLight.getBoundingClientRect();
  const titleRect = title.getBoundingClientRect();
  const afterStyle = window.getComputedStyle(title, '::after');

  return {
    imgRect,
    titleRect,
    afterWidth: afterStyle.width,
    afterHeight: afterStyle.height,
    afterTop: afterStyle.top,
    afterLeft: afterStyle.left,
  };
});","pageId":"934a78d4-0f43-4f24-8773-9ce29c8e85d4"}

