  const rgb = parseHex(hex);
  const [r, g, b] = [rgb.r / 255, rgb.g / 255, rgb.b / 255].map(v => 
    v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)
