{"command":"node -e '
import { byTheme } from "./formats/tokens/src/index.ts";

function parseHex(hex) {
  let h = hex.replace("#", "");
  if (h.length === 3) h = h.split("").map(c => c + c).join("");
  return {
    r: parseInt(h.substring(0, 2), 16),
    g: parseInt(h.substring(2, 4), 16),
    b: parseInt(h.substring(4, 6), 16),
  };
}

function relativeLuminance(hex) {
  const rgb = parseHex(hex);
  const [r, g, b] = [rgb.r / 255, rgb.g / 255, rgb.b / 255].map(v => 
    v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)
  );
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function contrastRatio(hex1, hex2) {
  const l1 = relativeLuminance(hex1);
  const l2 = relativeLuminance(hex2);
  const bright = Math.max(l1, l2);
  const dark = Math.min(l1, l2);
  return (bright + 0.05) / (dark + 0.05);
}

const tokens = byTheme("rebrand");
const tokenMap = new Map(tokens.map(t => [t.name, t.value]));

const scales = ["navy", "blue", "green", "red", "orange", "grey", "plum", "violet", "stone", "sky", "honey", "sea", "aurora"];
const bgLight = "#FFFFFF";

console.log("=== CONTRAST AGAINST WHITE (#FFFFFF) ===");
for (const s of scales) {
  const s120 = tokenMap.get(`--instui-primitive-color-${s}-${s}120`) || "";
  const s130 = tokenMap.get(`--instui-primitive-color-${s}-${s}130`) || "";
  const s170 = tokenMap.get(`--instui-primitive-color-${s}-${s}170`) || "";
  console.log(`${s.padEnd(8)} | step120 ${s120}: ${contrastRatio(s120, bgLight).toFixed(2)}:1 | step130 ${s130}: ${contrastRatio(s130, bgLight).toFixed(2)}:1 | step170 ${s170}: ${contrastRatio(s170, bgLight).toFixed(2)}:1`);
}
'","explanation":"Check contrast ratios against white for steps 120, 130, 170 across all scales","goal":"Analyze contrast ratios across steps","mode":"sync"}

