  // Click theme selector to open menu
  const selectorBtn = document.querySelector('.theme-selector__button');
  if (selectorBtn) selectorBtn.click();

  const getSwatchBg = (colorName) => {
    const btn = document.querySelector(`.theme-selector__color-item[title="${colorName}"] .theme-selector__swatch`);
    return btn ? window.getComputedStyle(btn).backgroundColor : null;
  };

  const rebrandRedLight = getSwatchBg('Red');
  const rebrandNavyLight = getSwatchBg('Navy');

  // Toggle dark mode
  document.documentElement.classList.add('dark');
  document.documentElement.style.colorScheme = 'dark';

  const rebrandRedDark = getSwatchBg('Red');
  const rebrandNavyDark = getSwatchBg('Navy');

  // Reset dark mode
  document.documentElement.classList.remove('dark');
  document.documentElement.style.colorScheme = 'light';

  // Switch to canvas
  const canvasThemeBtn = Array.from(document.querySelectorAll('.theme-selector__item')).find(el => el.textContent.trim() === 'Canvas');
  if (canvasThemeBtn) canvasThemeBtn.click();

  const canvasRed = getSwatchBg('Red');
  const canvasNavy = getSwatchBg('Navy');

